import React from "react";

export default function PersonalisedScoreCard({ personalEvaluation, onOpenProfileModal }) {
  if (!personalEvaluation) return null;

  const {
    personal_score = 100,
    personal_verdict = "Compatible",
    allergen_alerts = [],
    preference_conflicts = [],
    caution_items = [],
    preset_name = "custom",
    is_personalized = false
  } = personalEvaluation;

  const getScoreColor = (score) => {
    if (score >= 90) return "#16a34a"; // green
    if (score >= 70) return "#ca8a04"; // yellow/amber
    return "#dc2626"; // red
  };

  const hasAllergens = allergen_alerts && allergen_alerts.length > 0;
  const scoreColor = hasAllergens ? "#dc2626" : getScoreColor(personal_score);

  return (
    <div style={cardContainerStyle}>
      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <div>
          <h3 style={{ margin: 0, fontSize: "1.15rem", color: "#1e293b", display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <span>Personalised Dietary Assessment</span>
            {is_personalized && (
              <span style={{ fontSize: "0.75rem", padding: "0.2rem 0.5rem", borderRadius: "12px", backgroundColor: "#eff6ff", color: "#1d4ed8", fontWeight: 600, textTransform: "capitalize" }}>
                {preset_name.replace("_", " ")} Profile
              </span>
            )}
          </h3>
          <p style={{ margin: "0.25rem 0 0 0", fontSize: "0.8rem", color: "#64748b" }}>
            Tailored evaluation based on your individual dietary restrictions and configured allergens.
          </p>
        </div>
        {onOpenProfileModal && (
          <button
            onClick={onOpenProfileModal}
            style={{
              padding: "0.35rem 0.75rem",
              fontSize: "0.8rem",
              borderRadius: "6px",
              border: "1px solid #cbd5e1",
              backgroundColor: "#f8fafc",
              color: "#334155",
              cursor: "pointer",
              fontWeight: 500
            }}
          >
            Edit Profile
          </button>
        )}
      </div>

      {/* Critical Allergen Alert Banner */}
      {hasAllergens && (
        <div style={allergenBannerStyle}>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", fontWeight: "bold", fontSize: "0.95rem" }}>
            <span style={{ fontSize: "1.25rem" }}>⚠️</span>
            <span>CRITICAL ALLERGEN WARNING</span>
          </div>
          <div style={{ marginTop: "0.4rem", display: "flex", flexDirection: "column", gap: "0.35rem" }}>
            {allergen_alerts.map((alert, idx) => (
              <div key={idx} style={{ fontSize: "0.85rem", lineHeight: 1.4 }}>
                • <strong>{alert.allergen.toUpperCase()}:</strong> Detected token "<em>{alert.matched_term}</em>". {alert.action_required}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Score & Verdict Section */}
      <div style={{ display: "flex", alignItems: "center", gap: "1.5rem", padding: "1rem", backgroundColor: "#f8fafc", borderRadius: "8px", marginBottom: "1rem" }}>
        <div style={{
          width: "72px",
          height: "72px",
          borderRadius: "50%",
          backgroundColor: scoreColor,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          color: "#ffffff",
          flexShrink: 0
        }}>
          <span style={{ fontSize: "1.5rem", fontWeight: "bold", lineHeight: 1 }}>{hasAllergens ? "!" : personal_score}</span>
          <span style={{ fontSize: "0.65rem", opacity: 0.9 }}>/ 100</span>
        </div>

        <div>
          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
            <span style={{
              fontSize: "0.9rem",
              fontWeight: 700,
              padding: "0.2rem 0.6rem",
              borderRadius: "4px",
              backgroundColor: hasAllergens ? "#fee2e2" : personal_score >= 90 ? "#dcfce7" : personal_score >= 70 ? "#fef3c7" : "#fee2e2",
              color: scoreColor
            }}>
              {personal_verdict}
            </span>
          </div>
          <p style={{ margin: "0.4rem 0 0 0", fontSize: "0.82rem", color: "#475569" }}>
            {hasAllergens
              ? "Allergen triggers detected. Do not consume if you have severe intolerances."
              : personal_score >= 90
              ? "Product is fully compliant with your active dietary preferences."
              : personal_score >= 70
              ? "Product contains minor additives you prefer to limit. Review caution notes below."
              : "Product conflicts with one or more of your active dietary preferences."}
          </p>
        </div>
      </div>

      {/* Preference Conflicts List */}
      {preference_conflicts && preference_conflicts.length > 0 && (
        <div style={{ marginBottom: "1rem" }}>
          <h4 style={{ margin: "0 0 0.5rem 0", fontSize: "0.88rem", color: "#991b1b" }}>
            Specific Dietary Preference Conflicts ({preference_conflicts.length})
          </h4>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
            {preference_conflicts.map((c, i) => (
              <div key={i} style={conflictItemStyle}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span style={{ fontWeight: 600, color: "#991b1b" }}>{c.name} ({c.code})</span>
                  <span style={{ fontSize: "0.75rem", color: "#b91c1c", fontWeight: 600 }}>-{c.deduction} pts</span>
                </div>
                <div style={{ fontSize: "0.8rem", color: "#7f1d1d", marginTop: "0.15rem" }}>
                  {c.reason}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Caution Items */}
      {caution_items && caution_items.length > 0 && (
        <div>
          <h4 style={{ margin: "0 0 0.5rem 0", fontSize: "0.88rem", color: "#854d0e" }}>
            Dietary Caution Items ({caution_items.length})
          </h4>
          <div style={{ display: "flex", flexDirection: "column", gap: "0.4rem" }}>
            {caution_items.map((item, i) => (
              <div key={i} style={cautionItemStyle}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span style={{ fontWeight: 600, color: "#854d0e" }}>{item.name} ({item.code})</span>
                  <span style={{ fontSize: "0.75rem", color: "#a16207", fontWeight: 600 }}>-{item.deduction} pts</span>
                </div>
                <div style={{ fontSize: "0.8rem", color: "#713f12", marginTop: "0.15rem" }}>
                  {item.reason}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const cardContainerStyle = {
  backgroundColor: "#ffffff",
  border: "1px solid #e2e8f0",
  borderRadius: "10px",
  padding: "1.25rem",
  boxShadow: "0 1px 3px rgba(0, 0, 0, 0.05)",
  marginBottom: "1.5rem"
};

const allergenBannerStyle = {
  backgroundColor: "#fef2f2",
  border: "2px solid #ef4444",
  borderRadius: "8px",
  padding: "0.75rem 1rem",
  color: "#991b1b",
  marginBottom: "1rem"
};

const conflictItemStyle = {
  backgroundColor: "#fff5f5",
  borderLeft: "3px solid #ef4444",
  padding: "0.5rem 0.75rem",
  borderRadius: "4px"
};

const cautionItemStyle = {
  backgroundColor: "#fefce8",
  borderLeft: "3px solid #eab308",
  padding: "0.5rem 0.75rem",
  borderRadius: "4px"
};
